// All tile illustrations are bundled SVG. No web fonts, image files or network requests.
function tileArt(index, red) {
  const suit = index < 27 ? Math.floor(index / 9) : 3;
  const number = index % 9 + 1;
  const crimson = '#e45f62';
  const green = red ? crimson : '#299a77';
  const ink = '#365d68';
  const cream = '#fffdf0';
  const roundedText = `font-family="Microsoft YaHei, PingFang SC, sans-serif" font-weight="900" paint-order="stroke" stroke-width=".35" stroke-linejoin="round"`;
  let art = '';
  if (suit === 0) {
    const nums = ['一','二','三','四','五','六','七','八','九'];
    art = `<text x="24" y="28" text-anchor="middle" font-size="25" fill="${red ? crimson : ink}" stroke="${red ? crimson : ink}" ${roundedText}>${nums[number-1]}</text><text x="24" y="55" text-anchor="middle" font-size="27" fill="${crimson}" stroke="${crimson}" ${roundedText}>万</text>`;
  } else if (suit === 1) {
    if (number === 1) {
      art = `<circle cx="24" cy="33" r="17" fill="${ink}"/><circle cx="24" cy="33" r="12" fill="${cream}"/><circle cx="24" cy="33" r="8.2" fill="${green}"/><circle cx="24" cy="33" r="3.5" fill="${cream}"/>`;
    } else {
      art = pipLayouts[number].map(([x, y], i) => {
        const redPip = red || (number === 5 && i === 2) || (number === 7 && i >= 3) || (number === 9 && y === 33);
        const greenPip = number === 2 || (number === 3 && i === 1) || (number === 6 && y === 33) || (number === 7 && i < 3) || (number === 8 && i < 4);
        const color = redPip ? crimson : greenPip ? green : ink;
        const radius = number >= 7 ? 5.4 : 6.7;
        return `<circle cx="${x}" cy="${y}" r="${radius}" fill="${color}"/><circle cx="${x}" cy="${y}" r="${radius * .45}" fill="${cream}"/>`;
      }).join('');
    }
  } else if (suit === 2) {
    art = souzuArtwork[red && number === 5 ? 9 : number - 1];
  } else if (index === 31) {
    art = `<rect x="11" y="14" width="26" height="38" rx="5" fill="${cream}" stroke="#599ac0" stroke-width="4"/>`;
  } else {
    const color = index === 32 ? green : index === 33 ? crimson : ink;
    art = `<text x="24" y="46" text-anchor="middle" font-size="36" fill="${color}" stroke="${color}" ${roundedText}>${honors[index-27]}</text>`;
  }
  return `<svg viewBox="0 0 48 66" aria-hidden="true" focusable="false">${art}</svg>`;
}

function tile(index, { size = '', button = false, red = false, title = '' } = {}) {
  const tag = button ? 'button' : 'span';
  const label = `${red ? '赤' : ''}${tileName(index)}`;
  return `<${tag} class="tile ${size} ${button ? 'tile-button' : ''} ${red ? 'red' : ''}" data-index="${index}" data-red="${red ? '1' : '0'}" ${button ? 'type="button"' : ''} title="${escapeHTML(title || label)}" aria-label="${escapeHTML(label + (title ? '，' + title : ''))}">${tileArt(index, red)}</${tag}>`;
}

function renderTiles(element, parsed, { size = '', removable = false, empty = '' } = {}) {
  let html = '';
  for (let i = 0; i < 34; i++) for (let n = 0; n < parsed.counts[i]; n++) {
    const red = i < 27 && i % 9 === 4 && n < (parsed.reds?.[Math.floor(i / 9)] || 0);
    html += tile(i, { size, button: removable, red, title: removable ? '点击移除' : '' });
  }
  element.innerHTML = html || (empty ? `<span class="muted">${escapeHTML(empty)}</span>` : '');
}

function serialize(parsed) {
  let result = '';
  for (let s = 0; s < 4; s++) {
    let digits = '';
    for (let n = 0; n < (s === 3 ? 7 : 9); n++) {
      const count = parsed.counts[s * 9 + n];
      const reds = s < 3 && n === 4 ? Math.min(count, parsed.reds?.[s] || 0) : 0;
      digits += '0'.repeat(reds) + String(n + 1).repeat(count - reds);
    }
    if (digits) result += digits + 'mpsz'[s];
  }
  return result;
}

function parseEmpty(text) { return text.trim() ? parseTiles(text) : { counts: zero(), reds: [0, 0, 0], total: 0 }; }
function handLimit(melds = Number($('open-melds').value)) { return 14 - 3 * melds; }

// Keep the last parsable hand while allowing incomplete notation during typing.
// Reject the whole excessive edit rather than dropping or rearranging its tiles.
function readHandInput() {
  const field = $('hand-input');
  let hand = parseEmpty(field.value);
  const limit = handLimit();
  if (hand.total > limit) {
    field.value = state.acceptedHand;
    hand = parseEmpty(field.value);
    if (hand.total > limit) { field.value = ''; hand = parseEmpty(''); }
    toast(`手牌最多 ${limit} 张，已保留修改前的手牌。`);
  }
  state.acceptedHand = field.value;
  state.acceptedMelds = $('open-melds').value;
  return hand;
}

function restorePreferences(saved) {
  if (!saved || typeof saved.hand !== 'string') return;
  const rules = saved.rules === 'sanma' ? 'sanma' : 'yonma';
  let melds = /^[0-4]$/.test(String(saved.melds)) ? String(saved.melds) : '0';
  let hand = saved.hand;
  try {
    if (parseEmpty(hand).total > handLimit(Number(melds))) throw new Error('over-limit');
  } catch {
    hand = (rules === 'sanma' ? sanmaExamples : examples).two;
    melds = '0';
    toast('原保存手牌不符合输入上限，已载入何切示例。');
  }
  $('hand-input').value = hand;
  $('open-melds').value = melds;
  state.acceptedHand = hand;
  state.acceptedMelds = melds;
  setRules(rules, false);
}

function changeMelds() {
  const requested = $('open-melds').value;
  const limit = handLimit(Number(requested));
  let hand;
  try { hand = parseEmpty($('hand-input').value); }
  catch { hand = parseEmpty(state.acceptedHand); }
  if (hand.total > limit) {
    $('open-melds').value = state.acceptedMelds;
    toast(`先将手牌减至 ${limit} 张，再设置 ${requested} 组已完成面子。`);
    return;
  }
  state.acceptedMelds = requested;
  analyze();
}
function progressText(n) { return n === 0 ? '已听牌' : `差 ${n} 步`; }
function discardIsRed(index) { return index < 27 && index % 9 === 4 && state.hand?.counts[index] > 0 && state.hand.counts[index] === state.hand.reds[Math.floor(index / 9)]; }
function setError(message) { $('error').textContent = message; $('error').classList.toggle('hidden', !message); }
function toast(message) { $('toast').textContent = message; $('toast').classList.remove('hidden'); clearTimeout(state.timer); state.timer = setTimeout(() => $('toast').classList.add('hidden'), 2800); }

function switchView(view) {
  if (!['calculator', 'help', 'ai'].includes(view)) view = 'calculator';
  document.querySelectorAll('.salon-dialog[open]').forEach(dialog => dialog.close());
  state.view = view;
  if (view !== 'calculator') $(`view-${view}`).showModal();
  document.querySelectorAll('.main-nav [data-view]').forEach(el => { const active = el.dataset.view === view; el.classList.toggle('active', active); if (active) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current'); });
  try { history.replaceState(null, '', `${location.pathname}${location.search}#${view}`); } catch {}
}

async function openExternal(url) {
  if (!['https://gokujan.com/','https://tingque.ai/trial','https://mjai.ekyu.moe/','https://naga.dmv.nico/naga_report/top/'].includes(url)) return;
  try {
    if (window.pywebview?.api?.open_external) {
      const result = await window.pywebview.api.open_external(url);
      if (result?.ok === false) throw new Error(result.message || '未能打开系统浏览器。');
    } else window.open(url, '_blank', 'noopener,noreferrer');
  } catch (error) { toast(error.message); }
}

function renderPicker() {
  const pickerCell = (index, red = false) => `<span class="picker-cell" data-index="${index}" data-red="${red ? '1' : '0'}">${tile(index, { button: true, red, title: '左键添加，右键减少' })}<span class="picker-count hidden"></span></span>`;
  const sanma = state.rules === 'sanma';
  $('tile-picker').innerHTML = Array.from({ length: 4 }, (_, s) => {
    const indices = sanma && s === 0 ? [0,8] : Array.from({ length: s === 3 ? 7 : 9 }, (_, n) => s*9+n);
    return `<div class="picker-row ${s === 3 ? 'honor-row' : ''}"><span class="picker-row-label">${['万','筒','索','字'][s]}</span>${indices.map(index => pickerCell(index)).join('')}${sanma && s === 0 ? '<span class="sanma-picker-note">三麻：只用一万、九万</span>' : ''}${s === 3 ? `<span class="red-picks" title="赤五与普通五共用四张上限"><span class="red-label">赤</span>${(sanma ? [13,22] : [4,13,22]).map(index => pickerCell(index,true)).join('')}</span>` : ''}</div>`;
  }).join('');
  renderPickerCounts();
}

function setRules(rules, calculate = true) {
  state.rules = rules === 'sanma' ? 'sanma' : 'yonma';
  ['yonma','sanma'].forEach(name => { const active = state.rules === name; $(`rule-${name}`).classList.toggle('selected',active); $(`rule-${name}`).setAttribute('aria-pressed',String(active)); });
  renderPicker();
  if (calculate) analyze();
}

function renderPickerCounts() {
  document.querySelectorAll('.picker-cell').forEach(cell => {
    const index = Number(cell.dataset.index);
    const hand = state.hand?.counts[index] || 0;
    const current = state.hand;
    const isRed = cell.dataset.red === '1';
    const count = isRed ? current?.reds[Math.floor(index / 9)] || 0 : (current?.counts[index] || 0) - (index < 27 && index % 9 === 4 ? current?.reds[Math.floor(index / 9)] || 0 : 0);
    const badge = cell.querySelector('.picker-count');
    badge.textContent = count;
    badge.classList.toggle('hidden', !count);
    const button = cell.querySelector('button');
    const capped = (current?.total || 0) >= handLimit();
    const full = hand >= 4 || capped;
    cell.classList.toggle('full', full);
    button.setAttribute('aria-disabled', String(full));
    button.title = `${isRed ? '赤' : ''}${tileName(index)} · 手牌 ${hand} 张；${full ? `${capped ? `已达 ${handLimit()} 张上限` : '同种牌最多 4 张'}，右键仍可减牌` : '左键加，右键减'}`;
  });
}

function renderWaits(items) {
  if (!items.length) return '<span class="wait-label">这手牌暂时没有可列出的牌。</span>';
  return items.map(item => `<span class="wait-item ${item.remaining === 0 ? 'dead' : ''}" title="${escapeHTML(item.name)}，估算剩余 ${item.remaining} 张">${tile(item.index)}<span class="wait-count">${escapeHTML(item.name)} ${item.remaining}张</span></span>`).join('');
}

function explainResult(row, discardName) {
  if (row.shanten === 0) {
    const status = discardName ? `打出 ${discardName} 就能听牌。` : '这手牌已经听牌。';
    return status + (row.liveKinds ? '再拿到下方任意一种有剩余的牌，就能凑齐牌型。' : '按手牌估算，能等的牌已经用完。');
  }
  const status = `${discardName ? `打出 ${discardName} 后，` : ''}离听牌还差 ${row.shanten} 步。`;
  if (!row.liveKinds) return status + '目前没有剩余的牌能让手牌更接近听牌。';
  return status + (row.shanten === 1 ? '摸到下方任意一种还有剩余的牌，再打掉多余的牌，就能听牌。' : '摸到下方任意一种还有剩余的牌，就能更接近听牌。');
}

function renderHero(row, discard = null) {
  const isWait = row.shanten === 0;
  const discardName = discard === null ? null : `${discardIsRed(discard) ? '赤' : ''}${tileName(discard)}`;
  const complete = state.result?.mode === 'discard' && state.result.shanten === -1;
  const isFirstChoice = !complete && state.selected === state.result?.discards[0]?.index;
  const notice = complete ? '<p class="hero-sub">当前手牌已凑齐和牌所需的牌型。下面显示如果继续打牌会怎样。</p>' : '';
  $('hero-title').textContent = discard === null ? '这手牌还缺什么' : isFirstChoice ? '推荐先打这张' : '打出这张会怎样';
  $('shanten-badge').textContent = complete ? '当前牌型已凑齐' : progressText(row.shanten);
  $('hero-body').innerHTML = `${notice}<div class="hero-main">${discard === null ? `<div class="draw-call">${isWait ? '等哪些<br>牌' : '哪些牌<br>有用'}</div>` : `<div class="discard-call"><span>打出</span>${tile(discard, { size: 'large', red: discardIsRed(discard) })}</div>`}<div><div class="hero-number">${row.liveKinds}<small>种</small><span class="separator">/</span>${row.liveTotal}<small>张</small></div><div class="hero-sub">${escapeHTML(explainResult(row, discardName))}</div></div></div>`;
  $('wait-title').textContent = isWait ? '等这些牌' : '摸到这些牌有帮助';
  $('alive-summary').textContent = '按手牌估算张数';
  $('hero-foot').innerHTML = renderWaits(row.improving);
  const preview = { counts: state.hand.counts.slice(), reds: state.hand.reds.slice() };
  if (discard !== null) { preview.counts[discard]--; if (discardIsRed(discard)) preview.reds[Math.floor(discard / 9)]--; }
  $('after-title').textContent = discard === null ? '当前手牌' : '打出这张后留下的牌';
  $('shape-summary').textContent = `${state.hand.total - (discard === null ? 0 : 1)} 张`;
  renderTiles($('after-tiles'), preview, { size: 'mini' });
}

function renderResults() {
  const result = state.result;
  $('analysis-mode').textContent = result.mode === 'discard' ? '比较打出不同牌的结果' : '看看接下来摸什么牌有用';
  if (result.mode === 'discard') {
    $('result-title').textContent = '比较打出不同的牌';
    $('results-label').classList.remove('hidden');
    if (!result.discards.some(row => row.index === state.selected)) state.selected = result.discards[0]?.index;
    $('results-list').innerHTML = result.discards.map((row, i) => {
      const red = discardIsRed(row.index);
      const name = escapeHTML(`${red ? '赤' : ''}${row.name}`);
      const selected = row.index === state.selected;
      const progress = progressText(row.shanten);
      const accessibleProgress = row.shanten === 0 ? progress : `离听牌还${progress}`;
      return `<button class="result-row ${selected ? 'selected' : ''}" data-discard="${row.index}" aria-pressed="${selected}" aria-label="打出 ${name}，${accessibleProgress}，有用的牌 ${row.liveKinds} 种，估算 ${row.liveTotal} 张"><span class="result-discard"><span class="result-rank">${String(i+1).padStart(2,'0')}</span>${tile(row.index, { size: 'small', red })}<span>${name}</span></span><span>${progress}</span><span class="row-numbers"><strong>${row.liveKinds}</strong><small>种</small><strong>${row.liveTotal}</strong><small>张</small></span></button>`;
    }).join('');
    const selected = result.discards.find(row => row.index === state.selected);
    if (selected) renderHero(selected, selected.index);
  } else {
    state.selected = null;
    $('result-title').textContent = '怎么看结果';
    $('results-label').classList.add('hidden');
    $('results-list').innerHTML = '<div class="draw-details">上面列出下一张摸到会有帮助的牌。只要再加一张，就能比较打出哪张更合适。</div>';
    renderHero(result);
  }
}

function analyze(reset = true) {
  if (reset) { state.selected = null; $('results-list').scrollTop = 0; }
  state.result = null;
  let hand;
  try {
    hand = readHandInput();
    state.hand = hand;
    renderTiles($('hand-tiles'), hand, { removable: true, empty: '点击下面的牌盘添加手牌' });
    $('hand-count').textContent = `${hand.total} 张`;
    const melds = Number($('open-melds').value);
    const draw = 13 - melds * 3;
    $('hand-requirement').textContent = `${draw} 张看摸什么有用，${draw+1} 张看打哪张`;
    renderPickerCounts();
    state.result = analyzeHand({ counts: hand.counts, visible: zero(), openMelds: melds, rules: state.rules });
    setError(''); renderResults();
    const preferences = { hand: $('hand-input').value, melds: $('open-melds').value, rules: state.rules };
    try { localStorage.setItem('tingpai-desktop-v1', JSON.stringify(preferences)); } catch {}
    if (state.desktopReady && window.pywebview?.api?.save_state) window.pywebview.api.save_state(preferences).catch(() => {});
  } catch (error) {
    const empty = hand?.total === 0;
    const target = handLimit() - 1;
    const incomplete = hand && hand.total < target && error.message.startsWith('已有');
    setError(empty ? '' : incomplete ? `再加 ${target - hand.total} 张，就能查看摸什么牌有用。` : error.message);
    $('analysis-mode').textContent = '编辑手牌 · 补齐张数后自动计算';
    $('shanten-badge').textContent = '等待手牌';
    $('hero-title').textContent = '分析结果';
    $('hero-body').innerHTML = `<div class="empty-hero"><strong>${empty ? '先选几张牌。' : '先补齐手牌。'}</strong><span>${empty ? '可以点击牌盘，也可以粘贴手牌简写。' : '手牌张数合适后会自动显示结果。'}</span></div>`;
    $('wait-title').textContent = '有用的牌'; $('alive-summary').textContent = '';
    $('hero-foot').innerHTML = '<span class="wait-label">使用牌盘，或粘贴手牌简写。</span>';
    $('after-title').textContent = '手牌预览'; $('shape-summary').textContent = ''; $('after-tiles').innerHTML = '';
    $('result-title').textContent = '打哪张';
    $('results-label').classList.add('hidden');
    $('results-list').innerHTML = '<div class="empty-state">选好手牌后会自动分析。<br>也可以先点一手示例牌试试。</div>';
    if (!hand) { state.hand = null; $('hand-tiles').innerHTML = ''; $('hand-count').textContent = '检查输入'; }
    renderPickerCounts();
  }
}

function editTile(index, delta, red = false) {
  const field = $('hand-input');
  try {
    const parsed = parseEmpty(field.value);
    const suit = Math.floor(index / 9);
    const isFive = index < 27 && index % 9 === 4;
    if (delta < 0) {
      if (!parsed.counts[index]) return;
      if (red && !parsed.reds[suit]) return;
      if (isFive && !red && parsed.counts[index] === parsed.reds[suit]) red = true;
    }
    if (delta > 0) {
      const blocked = [];
      if (parsed.total >= handLimit()) blocked.push(`手牌最多 ${handLimit()} 张，请先减牌`);
      if (parsed.counts[index] >= 4) blocked.push(`${tileName(index)}最多 4 张`);
      if (blocked.length) return toast(blocked.join('；'));
    }
    parsed.counts[index] += delta;
    if (red && isFive) parsed.reds[suit] += delta;
    field.value = serialize(parsed); analyze();
  } catch (error) { setError(error.message); }
}

function selectDiscard(index, focus = false) {
  if (!state.result?.discards.some(row => row.index === index)) return;
  const previousScroll = $('results-list').scrollTop;
  state.selected = index; renderResults();
  $('results-list').scrollTop = previousScroll;
  if (focus) { const button = $('results-list').querySelector(`[data-discard="${index}"]`); button.focus({ preventScroll: true }); button.scrollIntoView({ block: 'nearest' }); }
}

async function download(name, content, type = 'application/json;charset=utf-8') {
  if (window.pywebview?.api?.save_json) {
    const result = await window.pywebview.api.save_json(content, name);
    if (result?.error) throw new Error(result.error);
    return;
  }
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement('a'); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1500);
}

function init() {
  renderPicker();
  document.querySelectorAll('[data-view]').forEach(button => button.addEventListener('click', event => { event.preventDefault(); switchView(button.dataset.view); }));
  document.querySelectorAll('[data-external]').forEach(button => button.addEventListener('click', () => openExternal(button.dataset.external)));
  document.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', () => switchView('calculator')));
  document.querySelectorAll('.salon-dialog').forEach(dialog => {
    dialog.addEventListener('close', () => { if (!document.querySelector('.salon-dialog[open]')) switchView('calculator'); });
    dialog.addEventListener('click', event => { const box = dialog.getBoundingClientRect(); if (event.target === dialog && (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom)) switchView('calculator'); });
  });
  document.querySelectorAll('[data-example]').forEach(button => button.addEventListener('click', () => { $('hand-input').value = (state.rules === 'sanma' ? sanmaExamples : examples)[button.dataset.example]; $('open-melds').value = '0'; analyze(); }));
  ['yonma','sanma'].forEach(rules => $(`rule-${rules}`).addEventListener('click', () => setRules(rules)));
  $('analyze').addEventListener('click', () => analyze());
  let inputTimer;
  $('hand-input').addEventListener('input', () => {
    clearTimeout(inputTimer);
    try { readHandInput(); } catch {}
    inputTimer = setTimeout(() => analyze(), 180);
  });
  $('open-melds').addEventListener('change', changeMelds);
  $('clear-hand').addEventListener('click', () => { $('hand-input').value = ''; analyze(); });
  $('tile-picker').addEventListener('click', event => { const cell = event.target.closest('.picker-cell'); if (cell) editTile(Number(cell.dataset.index), 1, cell.dataset.red === '1'); });
  $('tile-picker').addEventListener('contextmenu', event => { const cell = event.target.closest('.picker-cell'); if (cell) { event.preventDefault(); editTile(Number(cell.dataset.index), -1, cell.dataset.red === '1'); } });
  $('hand-tiles').addEventListener('click', event => { const button = event.target.closest('button[data-index]'); if (button) editTile(Number(button.dataset.index), -1, button.dataset.red === '1'); });
  $('results-list').addEventListener('click', event => { const button = event.target.closest('[data-discard]'); if (button) selectDiscard(Number(button.dataset.discard)); });
  $('results-list').addEventListener('keydown', event => { if (!['ArrowUp','ArrowDown','Home','End'].includes(event.key) || !state.result?.discards.length) return; event.preventDefault(); const rows = state.result.discards; let at = rows.findIndex(row => row.index === state.selected); if (event.key === 'Home') at = 0; else if (event.key === 'End') at = rows.length-1; else at = Math.max(0, Math.min(rows.length-1, at+(event.key === 'ArrowDown' ? 1 : -1))); selectDiscard(rows[at].index, true); });
  $('export-result').addEventListener('click', async () => { if (!state.result) return toast('先输入有效手牌。'); const content = JSON.stringify({ rules: state.rules, hand: $('hand-input').value, openMelds: Number($('open-melds').value), selectedDiscard: state.selected, result: state.result, note: '和牌形分析，不判断役、点数、防守与振听；张数按手牌与本次切牌估算，不是真实牌山余量。' }, null, 2); try { await download('雀见-分析结果.json', content); } catch (error) { toast(`保存失败：${error.message}`); } });
  document.addEventListener('keydown', event => {
    if (event.ctrlKey && event.key === 'Enter') { event.preventDefault(); analyze(); return; }
    if (!event.altKey || event.ctrlKey || event.metaKey) return;
    const key = event.key.toLowerCase();
    if (['1','2','3'].includes(key)) { event.preventDefault(); switchView(['calculator','help','ai'][Number(key)-1]); }
    else if (key === 'h') { event.preventDefault(); switchView('calculator'); $('hand-input').focus(); }
  });
  readHandInput();
  try { const params = new URLSearchParams(location.search); const saved = JSON.parse(localStorage.getItem('tingpai-desktop-v1') || localStorage.getItem('tingpai-lab-v1') || 'null'); const initial = params.has('hand') ? { hand: params.get('hand'), melds: params.get('melds') || '0', rules: params.get('rules') || 'yonma' } : saved; restorePreferences(initial); } catch {}
  window.addEventListener('pywebviewready', async () => {
    try {
      const saved = await window.pywebview.api.load_state();
      restorePreferences(saved);
    } catch {}
    state.desktopReady = true; analyze();
  });
  analyze(); switchView(location.hash.slice(1) || 'calculator');
}
init();
